//! Build script: embeds the app icon and product name into the Windows executable.

/// The icon embedded into the Windows executable, generated by the `gen_icons` example.
const ICON: &str = "assets/app-icon/icon.ico";

/// Embeds the Windows resources and tells Cargo when to rerun.
fn main() {
    println!("cargo:rerun-if-changed={ICON}");

    // Embed the app icon into the Windows executable. GPUI loads icon resource
    // ID 1 for the window/taskbar icon, which is what `set_icon` uses.
    #[cfg(windows)]
    {
        if !std::path::Path::new(ICON).exists() {
            println!("cargo:warning={ICON} missing; run `cargo run --example gen_icons`");
        } else if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
            let mut res = winresource::WindowsResource::new();
            res.set_icon(ICON).set("ProductName", "VLC").set("FileDescription", "VLC media player");
            res.compile().expect("failed to embed Windows resources");
        }
    }
}
